// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/todos", wrapper.ListTodos)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/todos", wrapper.CreateTodo)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/todos/completed", wrapper.DeleteCompletedTodos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/todos/archived", wrapper.ListArchivedTodos)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/todos/{id}", wrapper.DeleteTodo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/todos/{id}", wrapper.GetTodo)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/todos/{id}", wrapper.PatchTodo)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/todos/{id}", wrapper.UpdateTodo)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/todos/{id}/status", wrapper.UpdateTodoStatus)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/todos/{id}/archive", wrapper.ArchiveTodo)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/todos/{id}/restore", wrapper.RestoreTodo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/todos/{id}/history", wrapper.GetTodoHistory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users", wrapper.CreateUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{id}", wrapper.GetUser)

	return m
}
